// Mandatory neighbors of slots in a blue quadruple. Test each one-bit deletion with the other slots maximal. Monotonicity makes every failed deletion a necessary bit.
#[allow(dead_code)]mod run{include!("ramsey312_google_three_step.rs");pub fn go(){let args:Vec<_>=env::args().collect();let bs:Vec<_>=fs::read_to_string(&args[1]).unwrap().bytes().filter(|&b|b==48||b==49).collect();let mut a:Vec<M>=bs.chunks(52).map(|r|r.iter().enumerate().fold(0,|m,(i,&x)|m|(((x-48)as M)<<i))).collect();let z:Vec<_>=fs::read_to_string(&args[2]).unwrap().lines().nth(args[3].parse().unwrap()).unwrap().split_whitespace().map(str::to_owned).collect();let h=((1<<52)-1)^z[2].parse::<M>().unwrap();for e in &z[5..]{let(i,j)=e.split_once(':').unwrap();let(i,j):(usize,usize)=(i.parse().unwrap(),j.parse().unwrap());a[i]^=1<<j;a[j]^=1<<i}let mut cache=std::collections::HashMap::new();for line in fs::read_to_string(&args[4]).unwrap().lines().filter(|l|l.starts_with("Q ")){let q:Vec<M>=line.split_whitespace().skip(1).map(|v|v.parse().unwrap()).collect();let mut low=[0;4];for i in 0..4{let mut p=q[i];while p!=0{let b=bit(p);p^=b;for j in 0u32..16{if j>>i&1==0{continue}let mut union=q[i]^b;for k in 0..4{if k!=i&&j>>k&1==1{union|=q[k]}}let pair=(h&!union,12-j.count_ones());if *cache.entry(pair).or_insert_with(||has(&a,pair.0,pair.1)){low[i]|=b;break}}}}print!("B");for x in &q{print!(" {x}")}for x in &low{print!(" {x}")}println!()}}}fn main(){run::go()}
